mapper.select:
select * from ( select
b.MACHINE_NAME as lh_machine_name, regexp_replace(a.left_right_mold,'[L|R]','A') left_right_sort, c.class1_finish_qty, c.class2_finish_qty, c.class3_finish_qty, log.change_machine, log.change_class1_plan, log.change_class2_plan, log.change_class3_plan from t_lh_schedule_result a left join T_LH_MACHINE_INFO b on a.LH_MACHINE_CODE = b.MACHINE_CODE AND b.DEL_FLAG = '0' AND b.STATUS = '0' left join T_LH_CLASS_SHIFT_FINISH_QTY c on a.ORDER_NO = c.ORDER_NO and c.DEL_FLAG = '0' LEFT JOIN (/*调度员操作日志，判断调度员是否有做“转机台”或“调量”操作*/ SELECT schedule_id, max(decode(BEFORE_MACHINE_CODE, AFTER_MACHINE_CODE,0,1)) change_machine, max(decode(BEFORE_CLASS1_PLAN, AFTER_CLASS1_PLAN,0,1)) change_class1_plan, max(decode(BEFORE_CLASS2_PLAN, AFTER_CLASS2_PLAN,0,1)) change_class2_plan, max(decode(BEFORE_CLASS3_PLAN, AFTER_CLASS3_PLAN,0,1)) change_class3_plan FROM T_LH_DISPATCHER_LOG where schedule_date = #{scheduleDate} group by schedule_id ) log ON a.id = log.schedule_id where a.del_flag = '0' and a.schedule_date = #{scheduleDate} AND instr(a.sap_code,#{sapCode}) > 0 AND instr(a.embryo_code, #{embryoCode}) > 0 and a.LH_MACHINE_CODE = #{lhMachineCode} and a.production_status = #{productionStatus} and a.IS_RELEASE = #{isRelease ,jdbcType=VARCHAR} and a.id in #{scheduleId} order by b.machine_name asc,a.change_mold_time asc nulls first,left_right_sort asc,a.left_right_mold asc ) t
order by ${orderStr}

mapper.update:
update t_lh_schedule_result
batch_no = #{batchNo}, order_no = #{orderNo}, lh_machine_code = #{lhMachineCode}, lh_machine_name = #{lhMachineName}, left_right_mold = #{leftRightMold}, sap_code = #{sapCode}, spec_desc = #{specDesc}, stock_area = #{stockArea}, lh_time = #{lhTime}, daily_plan_qty = #{dailyPlanQty}, schedule_date = #{scheduleDate}, production_status = #{productionStatus}, class1_plan_qty = #{class1PlanQty,jdbcType=DECIMAL}, class1_analysis = #{class1Analysis}, class1_analysis_input = #{class1AnalysisInput,jdbcType=VARCHAR}, class2_plan_qty = #{class2PlanQty,jdbcType=DECIMAL}, class2_analysis = #{class2Analysis}, class2_analysis_input = #{class2AnalysisInput,jdbcType=VARCHAR}, class3_plan_qty = #{class3PlanQty,jdbcType=DECIMAL}, class3_analysis = #{class3Analysis}, class3_analysis_input = #{class3AnalysisInput,jdbcType=VARCHAR}, is_release = #{isRelease}, create_by = #{createBy}, create_time = #{createTime}, update_by = #{updateBy}, update_time = #{updateTime}, del_flag = #{delFlag}, embryo_code = #{embryoCode}, remark = #{remark,jdbcType=VARCHAR},
where id = #{id}

